import { Box } from '@mui/system';
import React, { useContext, useEffect, useState } from 'react';
import { SkillItem, useAllSkills } from '../../hooks/useAllSkills';
import { TheAppContext } from '../../provider/AppContext';

import SingleSkillMastery from './SingleSkillMastery';

const SkillMastery = () => {
  const { skills, timeRange } = useAllSkills();
  const { skillControl } = useContext(TheAppContext);
  const [filteredSkills, setFilteredSkills] = useState<SkillItem[]>([]);

  useEffect(() => {
    if (skills && filteredSkills.length === 0) setFilteredSkills(skills);
  }, [skills]);

  useEffect(() => {
    const skillsToShow = skillControl
      .filter((c) => c.activated)
      .flatMap((s) => s.slug);

    setFilteredSkills((prev) =>
      skills.filter((s) => skillsToShow.includes(s.attributes.SkillCategory)),
    );
  }, [skillControl]);

  return (
    <Box
      sx={{
        display: 'flex',
        flexWrap: 'wrap',
        justifyContent: 'center',
        gap: '1rem',
        maxWidth: 'calc(1024px + 2rem)',
        mx: 'auto',
        pb: 5,
      }}
    >
      {skills &&
        skills.map((skill, index) => (
          <SingleSkillMastery
            key={`${skill.id}--${skill.attributes.slug}`}
            skill={skill}
            timeRange={timeRange}
            index={index}
            activated={filteredSkills.flatMap((s) => s.id).includes(skill.id)}
          />
        ))}
    </Box>
  );
};

export default SkillMastery;
