import { graphql, useStaticQuery } from 'gatsby';

export type SingleProjectResponse = {
  id: string;
  Title: string;
  Completed: string;
  RepoLink: string;
  LiveLink: string;
  Cover: {
    url: string;
    name: string;
  };
  tags: { tagName: string; id: string }[];
  skills: {
    SkillCategory: 'frontend' | 'backend' | 'creative' | 'other';
    id: string;
    skill: { SkillName: string; id: string; strapi_id: number };
  }[];
  Narrative: {
    data: {
      childMarkdownRemark: {
        excerpt: string;
        timeToRead: number;
        html: HTMLBodyElement;
      };
    };
  };
};

type ProjectResponse = {
  projects: { nodes: SingleProjectResponse[] };
};

export const useAllProjects = () => {
  const data = useStaticQuery<ProjectResponse>(graphql`
    {
      projects: allStrapiProject(limit: 100, sort: { Completed: DESC }) {
        # projects: allStrapiProject(sort: { Completed: DESC }, limit: 100) {
        nodes {
          Title
          Completed
          Narrative {
            data {
              childMarkdownRemark {
                excerpt
                timeToRead
                html
              }
            }
          }
          RepoLink
          id
          Cover {
            url
            name
          }
          tags {
            tagName
            id
          }
          skills {
            SkillCategory
            skill {
              SkillName
              id
              strapi_id
            }
          }
        }
      }
    }
  `);

  return data?.projects?.nodes;
};
