import { Box, Typography } from '@mui/material';
import React from 'react';
import { Draggable } from 'react-beautiful-dnd';
import { CSSTransition } from 'react-transition-group';
import { SkillBoardItem } from './Scrumboard';

const SingleSkill = ({
  data: skillItem,
  index,
}: {
  data: SkillBoardItem;
  index: number;
}) => {
  return (
    <CSSTransition
      in={skillItem.activated}
      timeout={300 + index * 10}
      classNames="example"
    >
      <Draggable draggableId={skillItem.id} index={index}>
        {(provided, snapshot) => (
          <div
            style={{
              ...provided.draggableProps.style,
              opacity: snapshot.isDragging ? 1 : 'inherit',
            }}
            ref={provided.innerRef}
            {...provided.draggableProps}
            {...provided.dragHandleProps}
            className={`single-skill ${skillItem.attributes.SkillCategory.toLowerCase()}--skill ${
              skillItem.activated ? '' : 'single-skill--off'
            } `}
          >
            <Box
              className="skill-icon"
              sx={{
                width: '32px',
                height: '32px',
                bgcolor: 'white',
                overflow: 'hidden',
                borderRadius: '100%',
                display: 'flex',
                justifyContent: 'center',
              }}
            >
              <img
                style={{ width: '100%', height: 'auto', borderRadius: '100%' }}
                src={skillItem.attributes.skill.Icon.data.attributes.url}
                alt={skillItem.attributes.skill.SkillName}
              />
            </Box>

            <div className="single-skill--content">
              <Typography>
                <strong>{skillItem.attributes.skill.SkillName}</strong>
              </Typography>
            </div>
            <div className="single-skill--drag">
              <span></span>
              <span></span>
              <span></span>
            </div>
          </div>
        )}
      </Draggable>
    </CSSTransition>
  );
};

export default SingleSkill;
