import React from 'react';
import { Box, Button } from '@mui/material';
import cn from 'classnames';
import * as styles from './skillLegend.module.css';
const SingleSkillLegend = ({
  toggle_square,
  activated,
  index,
  DisplayName,
}: any) => {
  return (
    <Box>
      <Box sx={{ display: 'block' }}>
        <Box
          className={styles.toggle}
          sx={{ cursor: 'pointer' }}
          onClick={() => toggle_square(index)}
        >
          <input
            type={`checkbox`}
            checked={activated}
            onChange={(e) => e.preventDefault()}
          />
          <span></span>
        </Box>
      </Box>
      <Button
        className={cn(
          `${DisplayName.toLowerCase().replace(/ /gi, '')}--skill`,
          { 'skill-square--off': !activated },
        )}
        sx={{
          textTransform: 'unset',
          minWidth: '100px',
          minHeight: '50px',
          borderRadius: 0,
          borderBottomLeftRadius: index === 0 ? '30px' : '0px',
          borderTopLeftRadius: index === 0 ? '30px' : '0px',
          borderBottomRightRadius: index === 4 ? '30px' : '0px',
          borderTopRightRadius: index === 4 ? '30px' : '0px',
          ':hover': {
            backgroundColor: 'var(--as-light-grey)',
            opacity: 1,
          },
        }}
        onClick={() => toggle_square(index)}
      >
        <center>{DisplayName}</center>
      </Button>
    </Box>
  );
};

export default SingleSkillLegend;
